-- flyw8t initial schema.
--
-- Conventions: UUID primary keys generated by the database; timestamptz everywhere;
-- secrets stored only as SHA-256 digests (bytea); history tables are append-only and
-- enforced by trigger, not by convention.

CREATE FUNCTION flyw8t_forbid_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'table % is append-only', TG_TABLE_NAME;
END;
$$;

-- Tenancy -----------------------------------------------------------------------------

CREATE TABLE organizations (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (name)
);

CREATE TABLE sites (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
    name             text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (organization_id, name),
    UNIQUE (organization_id, id)
);

-- People and credentials --------------------------------------------------------------

CREATE TABLE users (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email          text NOT NULL UNIQUE CHECK (email = lower(email) AND position('@' in email) > 1),
    display_name   text NOT NULL,
    password_hash  text NOT NULL,
    role           text NOT NULL CHECK (role IN ('admin', 'technician', 'readonly')),
    created_at     timestamptz NOT NULL DEFAULT now(),
    disabled_at    timestamptz
);

-- Organizations a non-admin user may see and act in. Admins span all organizations.
CREATE TABLE user_organizations (
    user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, organization_id)
);

CREATE TABLE sessions (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash    bytea NOT NULL UNIQUE,
    csrf_token    text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    revoked_at    timestamptz,
    client_ip     text,
    user_agent    text
);
CREATE INDEX sessions_user ON sessions (user_id);

-- Personal access tokens for API callers (e.g. AnchorDesk). Shown once; hash stored.
CREATE TABLE api_tokens (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name          text NOT NULL,
    prefix        text NOT NULL,
    token_hash    bytea NOT NULL UNIQUE,
    scopes        text[] NOT NULL CHECK (scopes <@ ARRAY['read', 'jobs:run']::text[] AND cardinality(scopes) > 0),
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz,
    last_used_at  timestamptz,
    revoked_at    timestamptz
);

-- Devices -----------------------------------------------------------------------------

CREATE TABLE enrollment_tokens (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    site_id          uuid,
    token_hash       bytea NOT NULL UNIQUE,
    created_by       uuid NOT NULL REFERENCES users(id),
    created_at       timestamptz NOT NULL DEFAULT now(),
    expires_at       timestamptz NOT NULL,
    max_uses         integer NOT NULL CHECK (max_uses BETWEEN 1 AND 1000),
    uses             integer NOT NULL DEFAULT 0 CHECK (uses >= 0 AND uses <= max_uses),
    revoked_at       timestamptz,
    CHECK (expires_at > created_at),
    FOREIGN KEY (organization_id, site_id) REFERENCES sites (organization_id, id)
);

CREATE TABLE devices (
    id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id       uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
    site_id               uuid,
    -- Device-reported display facts. Never used for authorization.
    hostname              text NOT NULL,
    os_family             text NOT NULL,
    agent_version         text,
    enrolled_at           timestamptz NOT NULL DEFAULT now(),
    enrolled_via          uuid REFERENCES enrollment_tokens(id) ON DELETE SET NULL,
    last_seen_at          timestamptz,
    last_connected_at     timestamptz,
    last_disconnected_at  timestamptz,
    retired_at            timestamptz,
    FOREIGN KEY (organization_id, site_id) REFERENCES sites (organization_id, id),
    UNIQUE (organization_id, id)
);
CREATE INDEX devices_org ON devices (organization_id);
CREATE INDEX devices_hostname ON devices (lower(hostname));

CREATE TABLE device_credentials (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    device_id       uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    algorithm       text NOT NULL CHECK (algorithm = 'ed25519'),
    public_key      bytea NOT NULL UNIQUE CHECK (length(public_key) = 32),
    created_at      timestamptz NOT NULL DEFAULT now(),
    revoked_at      timestamptz,
    revoked_reason  text
);
-- At most one live credential per device.
CREATE UNIQUE INDEX device_credentials_one_active ON device_credentials (device_id) WHERE revoked_at IS NULL;

CREATE TABLE inventory_snapshots (
    id            bigserial PRIMARY KEY,
    device_id     uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    collected_at  timestamptz NOT NULL,   -- device clock
    received_at   timestamptz NOT NULL DEFAULT now(),  -- server clock
    source        text NOT NULL CHECK (source IN ('periodic', 'job')),
    data          jsonb NOT NULL
);
CREATE INDEX inventory_latest ON inventory_snapshots (device_id, received_at DESC);

-- Jobs --------------------------------------------------------------------------------

CREATE TABLE jobs (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id      uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
    device_id            uuid NOT NULL,
    action               text NOT NULL,
    request              jsonb NOT NULL,
    timeout_secs         integer NOT NULL CHECK (timeout_secs BETWEEN 1 AND 3600),
    requested_by         uuid NOT NULL REFERENCES users(id),
    request_channel      text NOT NULL CHECK (request_channel IN ('web', 'api')),
    idempotency_key      text,
    state                text NOT NULL CHECK (state IN ('created', 'authorized', 'queued', 'dispatched',
                             'acknowledged', 'running', 'completed', 'failed', 'timed_out',
                             'cancelled', 'expired', 'outcome_unknown')),
    verification         text NOT NULL DEFAULT 'pending'
                             CHECK (verification IN ('pending', 'verified', 'failed', 'not_applicable')),
    verification_note    text,
    state_note           text,
    created_at           timestamptz NOT NULL DEFAULT now(),
    deliver_by           timestamptz NOT NULL,
    queued_at            timestamptz,
    first_dispatched_at  timestamptz,
    dispatch_count       integer NOT NULL DEFAULT 0,
    -- Server connection the latest offer was written to. Redelivery happens only on a
    -- different connection: one WebSocket is ordered and reliable.
    last_dispatch_conn   uuid,
    acknowledged_at      timestamptz,
    started_at           timestamptz,   -- device clock
    finished_at          timestamptz,   -- device clock
    terminal_at          timestamptz,   -- server clock
    cancel_requested_at  timestamptz,
    cancel_requested_by  uuid REFERENCES users(id),
    exit_code            integer,
    stdout               text,
    stdout_truncated     boolean,
    stderr               text,
    stderr_truncated     boolean,
    result               jsonb,
    error                text,
    UNIQUE (requested_by, idempotency_key),
    -- A job's organization is its device's organization; the database enforces it.
    FOREIGN KEY (organization_id, device_id) REFERENCES devices (organization_id, id) ON DELETE RESTRICT
);
CREATE INDEX jobs_device ON jobs (device_id, created_at DESC);
CREATE INDEX jobs_open ON jobs (state) WHERE state IN ('queued', 'dispatched', 'acknowledged', 'running');
CREATE INDEX jobs_org_created ON jobs (organization_id, created_at DESC);

-- Every transition and every notable report, including ones that changed nothing.
CREATE TABLE job_events (
    id          bigserial PRIMARY KEY,
    job_id      uuid NOT NULL REFERENCES jobs(id) ON DELETE RESTRICT,
    at          timestamptz NOT NULL DEFAULT now(),
    kind        text NOT NULL,
    from_state  text,
    to_state    text,
    actor       text NOT NULL,
    detail      jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX job_events_job ON job_events (job_id, id);
CREATE TRIGGER job_events_append_only BEFORE UPDATE OR DELETE ON job_events
    FOR EACH ROW EXECUTE FUNCTION flyw8t_forbid_mutation();
CREATE TRIGGER job_events_no_truncate BEFORE TRUNCATE ON job_events
    FOR EACH STATEMENT EXECUTE FUNCTION flyw8t_forbid_mutation();

-- Audit -------------------------------------------------------------------------------

CREATE TABLE audit_events (
    id               bigserial PRIMARY KEY,
    at               timestamptz NOT NULL DEFAULT now(),
    actor_type       text NOT NULL CHECK (actor_type IN ('user', 'device', 'system', 'anonymous')),
    actor_id         uuid,
    actor_label      text NOT NULL,
    channel          text NOT NULL,
    credential       text,
    organization_id  uuid,
    action           text NOT NULL,
    target_type      text,
    target_id        uuid,
    outcome          text NOT NULL CHECK (outcome IN ('success', 'denied', 'failed')),
    client_ip        text,
    detail           jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_at ON audit_events (at DESC);
CREATE INDEX audit_org ON audit_events (organization_id, at DESC);
CREATE TRIGGER audit_events_append_only BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION flyw8t_forbid_mutation();
CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events
    FOR EACH STATEMENT EXECUTE FUNCTION flyw8t_forbid_mutation();
